T[24]={"^Increases movement speed by 60%% while in Cat Form%.%s*$","Aumenta a velocidade de movimento em 60% enquanto estiver em Forma de Felino."}
T[25]={"^Increases movement speed by 70%% while in Cat Form%.%s*$","Aumenta a velocidade de movimento em 70% enquanto estiver em Forma de Felino."}
T[26]={"^Block chance increased by (.-)%% and block value increased by (.-)%%%.%s*$","Aumenta a chance de bloqueio em {{1}}% e o valor do bloqueio em {{2}}%."}
