T[1582]={"^Physical Damage Taken from the Barbarian increased by (.-)%%%.%s*$","O dano físico recebido do Bárbaro aumenta em {{1}}%."}
T[1583]={"^In stasis%.%s*$","Em estase."}
T[1584]={"^Magic Resistance increased by (.-)%.%s*$","AumentaDá resistência à magia em {{1}}."}
T[1585]={"^Your Wand of Time ability can affect up to (.-) additional enemies near your primary target%.%s*$","Sua habilidade Vara do Tempo pode afetar até {{1}} inimigos adicionais perto de seu alvo principal."}
T[1586]={"^Wand attacks cause additional Arcane damage%.%s*$","Os ataques com varinha causam dano arcánico adicional."}
