T[1588]={"^Damage taken reduced by (.-)%%%. Healing received increased by (.-)%%%.%s*$","O dano recebido é reduzido em {{1}}%. A cura recebida aumenta em {{2}}%"}
T[1589]={"^Armor reduced by (.-)%%%.%s*$","Armadura reduzida em {{1}}%."}
