T[1738]={"^Causes your critical strikes to generate a stack of Zephyr%.%s*$","Faz seus acertos críticos gerem um acúmulo de Zefirio."}
T[1739]={"^Causes physical critical strikes to reduce the remaining cooldown of |cffffffffBurning Banner|r by (.-) sec%.%s*$","Reduz o tempo de recarga de |cffffffffEstandarte Ardente|r em {{1}} s quando se produza um acerto crítico físico."}
T[1740]={"^Healing received increased by (.-)%%%.%s*$","Cura recebida aumentada em {{1}}%."}
T[1741]={"^You take (.-)%% reduced damage from the monk, but all damage you deal is reduced%.%s*$","Tomas {{1}}% menos dano do monge, mas todo dano que causa é reduzido."}
T[1742]={"^Spell power increased based on Agility%. Attack power increased based on Intellect%.%s*$","Poder Mágico aumentou baseado em Agilidade. Poder de ataque aumentado baseado em Intelecto."}
