T[7109]={"^Deadly Poison deals (.-)%% and Rogue bleeds deal (.-)%% more damage%.%s*$","Dano de Veneno Letal causa {{1}}% e as hemorragias do Assassino causam {{2}}% mais dano."}
T[7110]={"^Chimera Shot, Envenom, Deadly Throw and Mortal Strike consume 5 stacks to grant you Venom Coated Blade%.%s*$","Chimera Shot, Envenom, Deadly Throw e Mortal Strike consomem 5 acúmulos para conceder a você Lâmina envenenada."}
T[7111]={"^Envenom preserves (.-) combo points and increases the damage done by Warrior abilities by (.-)%%%.%s*$","Envenom preserva {{1}} pontos de combo e aumenta o dano causado pelas habilidades do Guerreiro em {{2}}%."}
T[7112]={"^Increases the damage done of Explosive Shot by (.-)%% and critical strike chance of Explosive Shot by (.-)%% to targets affected by your Living Bomb%.%s*$","Aumenta o dano de Tiro explosivo em {{1}}% e a Chance de Acerto Crítico de Tiro explosivo em {{2}}% paraos alvos afecdadeos por Caolho bomba."}
T[7113]={"^Increases the damage dealt with Explosive Trap by (.-)%% and Immolation Trap by (.-)%%%.%s*$","Aumenta o dano de Explosive Trap em {{1}}% e o de Immolation Trap em {{2}}%."}
T[7114]={"^Your next Mongoose Bite, Raptor Strike or Counterattack to deal bonus Fire damage%.%s*$","Seu próximo Mordida de guepardo, Assalto raptores ou Contragolpe causa um bônus de dano de Fogo."}
