T[11565]={"^Increases all Holy Damage by (.-)%% for (.-)%.%s*$","Aumenta todo dano Sagrado em {{1}}% durante {{2}}."}
T[11566]={"^Direct damage dealt will deal additional Froststorm Damage%.%s*$","O dano direto causado causa dano adicional Tempestade Gelo."}
T[11567]={"^Increases damage done by (.-)%% and physical damage by (.-)%%%.%s*$","Aumenta o dano causado em {{1}}% e o dano físico em {{2}}%."}
T[11568]={"^Increases damage done by (.-)%%%.%s*$","Aumenta o dano causado {{1}}%."}
