T[11593]={"^Threat generated increased by (.-)%%%. Threat generated from Holy spells and abilities increased by (.-)%%%.%s*$","Ameaça gerada aumentada em {{1}}%. Ameaça gerada por feitiços Sagrados e habilidades aumentada em {{2}}%."}
T[11594]={"^Threat generated increased by (.-)%%%. Threat generated from Holy spells and abilities increased by (.-)%%%.%s*$","Ameaça gerada aumentada em {{1}}%. Ameaça gerada por feitiços Sagrados e habilidades aumentada em {{2}}%."}
T[11595]={"^Threat generated by (.-)%%, doubled for Arcane spells and abilities%.%s*$","A ameaça gerada aumenta em {{1}}%, dobrado para feitiços e habilidades Arcanas."}
