T[12811]={"^Increases the damage of your next Desolate Wind Bolt by (.-)%%%.%s*$","Aumenta o dano de sua próxima Flecha do Vento Desolado em {{1}}%."}
T[12812]={"^Your direct heals grant you Restoring Tides%. Mana Tide Totem now also heals for 200%% of Healing Stream Totem's effect%.\n\nRestoring Tides increase the periodic healing of Healing Stream Totem by %% per stack%.%s*$","Seus curações directas te concedem Marés Restauradoras. O Totém de Maré Mana agora também cura em 200% do efeito do Totém de Corrente de Cura.\n\nMarés Restauradoras aumentam a cura periódica do Totém de Corrente de Cura em % por acúmulo."}
T[12813]={"^Earth Shock increases your Reckoning proc chance by 15%% for 8 seconds%. Dealing damage with Reckoning will allow your Earth Shock to hit up to 3 enemies%.%s*$","O acerto de Terra aumenta sua chance de ativação de Reckoning em 15% durante 8 segundos. Causar dano com Reckoning permitirá que seu acerto de Terra golpeie até a 3 inimigos."}
T[12814]={"^Earth Shock can now jump to 3 targets%s*$","O acerto de Terra agora pode saltar 3 alvos"}
T[12815]={"^Your next Doomglaive will trigger a Felstrike%.%s*$","Sua próxima Doomglaive será ativado um Felstrike."}
T[12816]={"^Dealing (.-) Shadow damage around it every 2 seconds%.%s*$","Causa {{1}} dano de Sombra ao redor seu a cada 2 segundos."}
T[12817]={"^Arngrim's Greeting Dummy SLS%s*$","Saudação de Arngrim SLS"}
T[12818]={"^Damage done by your Mongoose Bite or Counterattack increased by (.-)%%, and mana cost reduced by (.-)%%%.%s*$","O dano causado por Seu Bocado de Mungo ou Contragolpe aumenta em {{1}}%, e o custo de mana é reduzido em {{2}}%."}
T[12819]={"^sls for 997238\nApplies Serpent Sting to targets struck by Multi%-Shot, wont overwrite current applications%.%s*$","sls para 997238\nAplica Picada de Serpente aos alvos atingidos por Tiro Multitudinario, não sobrescribe as aplicações atuais."}
