T[13110]={"^Devastate deals (.-)%% additional damage and reduces the target's armor by an additional (.-)%% for (.-)%.%s*$","Devastate causa dano adicional de {{1}}% e reduz a armadura do alvo em um adicional do {{2}}% durante {{3}}."}
T[13111]={"^Your next Devastate deals (.-)%% additional damage%.%s*$","Seu próximo Devastar causa {{1}}% de dano adicional."}
T[13112]={"^Your next Mortal Strike deals (.-)%% increased damage and has a (.-)%% increased critical strike chance%. Your next Thunder Clap sends out an aftershock, dealing (.-)%% weapon damage%.%s*$","Seu próximo acerto mortal causa dano aumentado em {{1}}% e tem uma maior Chance de Acerto Crítico do {{2}}%. Seu próximo Rugido de trovão envia um sismo, causando o {{3}}% de seu dano da arma."}
T[13113]={"^Increases the healing of your next Chain Heal by (.-)%%%.%s*$","Aumenta a cura de sua próxima Cadeia de Cura em {{1}}%."}
T[13114]={"^Consume 3 stacks to empower Shield of Righteousness or Avenger's Shield%.%s*$","Consumir 3 acúmulos para fortalecer Escudo de Retidão ou Escudo do Vingador."}
