T[13147]={"^Your bleeds deal (.-)%% increased damage%. Eviscerate and Dispatch deal (.-)%% increased%.%s*$","Seus hemorragias causam dano aumentado de {{1}}%. Eviscerate e Dispatch causam dano aumentado em {{2}}%."}
T[13148]={"^Increases your critical damage bonus by 20%%%.%s*$","Aumenta seu bonificação de dano por acerto crítico em 20%."}
T[13149]={"^Increases all rage costs by (.-)%% and lower warrior global cooldowns by (.-)%%%.%s*$","Aumenta todos os custos de raiva em {{1}}% e reduz o tempo de recarga global das habilidades do Guerreiro em {{2}}%."}
T[13150]={"^Increases your Rage costs by (.-)%%, lowers your global cooldowns of Warrior abilities by (.-)%% per stack %(cannot go lower than 1 sec%)%.%s*$","Aumenta seus custos de raiva em {{1}}%, reduz o tempo de recarga global das habilidades do Guerreiro em {{2}}% por acúmulo (não pode ser reduzida a menos que 1 s)."}
