T[13532]={"^Damage taken reduced%.%s*$","O dano recebido é reduzido."}
T[13533]={"^You have been frozen in ice!%s*$","Tem banido congelado em gelo！"}
T[13534]={"^Up to lotsa good%s*$","Até muito lió"}
T[13535]={"^Participating in the Prestige Challenge%.\nMassively Increases all experience gained%. This is a multiplicative boost%.%s*$","Participando no desafio de Prestígio.\nAumenta enormemente toda experiência obtida. Esta é uma melhoria multiplicativa."}
T[13536]={"^May only engage in single combat%.%s*$","Só pode enfrentar em combate individual."}
