T[15721]={"^              __/%)\n           %.%-%(__%(=:\n        |\\ |    \\%)\n         \\ ||\n         \\||\n          \\|\n           |\n\nWild Magic spawns around this creature, periodically healing both allies and enemies within it's radius%.%s*$"," __/).-(__(=:\n|\\ | \\)\n\\ ||\n\\||\n\\|\n|\n\nMagia selvagem aparecem ao redor de esta criatura, curando tanto a aliados como a inimigos dentro de seu raio."}
T[15722]={"^Increases run and swim speed by (.-)%% for (.-)%.%s*$","Aumenta a velocidade de corrida e natação em {{1}}% durante {{2}}."}
T[15723]={"^Removes (.-) magic, curse, poison or disease effect on you every (.-) seconds for (.-)%.%s*$","Elimina {{1}} efeito de magia, maldição, veneno ou doença em ti a cada {{2}} segundos durante {{3}}."}
T[15724]={"^These magic flowers are healing you for (.-)%% and creatures for (.-)%% every (.-)%.%s*$","Estas flores mágicos cura você em {{1}}% e às criaturas em {{1}}% a cada {{3}}."}
T[15725]={"^Deals (.-)%% frost damage to you and (.-)%% frost damage to creatures every (.-) and reduces movement speed by (.-)%%%.%s*$","Causa dano de Gelo do {{1}}% a ti e do {{2}}% às criaturas cada {{3}} e reduz a velocidade de movimento em {{4}}%."}
T[15726]={"^Empowered by the twisted magic of the manastorm, this creature leeches power from its nearby allies, increasing its health by (.-)%% and its damage by (.-)%%%.\n\nKilling nearby enemies causes this effect to fade%.%s*$","Fortalecido pela magia retorcida da manastorm, esta criatura absorve poder de seus aliados próximos, aumentando sua vida em {{1}}% e seu dano em {{2}}%.\n\nMatando a inimigos próximos Faz com que este efeito desapareça."}
T[15727]={"^Grants immunity to all impairing mechanics for (.-)%.%s*$","Concede a você Imunidade a todas as mecânicos nocivos durante {{1}}."}
T[15728]={"^Use this item to unlock access to the Bronzebeard: Original 9 Class Realm%.%s*$","Usa este item para desbloquear o acesso ao Reino de Classe Original 9 de Bronzabarbudo."}
T[15729]={"^Causes Fire damage based on the total damage of your Explosive Shot%.%s*$","Causa dano de Fogo baseado no total do dano de seu Disparo Explosivo."}
T[15730]={"^Forces movement toward the caster%.%s*$","Forzao movimento em direção ao conjurador."}
T[15731]={"^Regenerating (.-)%% maximum health every (.-) sec%.%s*$","Regenerando {{1}}% de vida máxima a cada {{2}} s."}
